actions.script:
const out = ec.service.sync().name('org.moqui.comms.InboxServices.run#Operation').parameters({operation: 'get#MessageDetail', parameters: {emailMessageId: emailMessageId || null,
    communicationEventId: communicationEventId || null}}).call()?.result || {}
if (!ec.message.hasError() && !out.detail?.canResend) ec.message.addError(ec.l10n.localize('This message cannot be sent again'))
if (!ec.message.hasError()) {
    const sent = ec.service.sync().name('org.moqui.impl.EmailServices.send#EmailMessage').parameter('emailMessageId', out.detail.emailMessageId).call()
    if (!ec.message.hasError()) ec.message.addMessage(sent.sendError ? ec.l10n.localize('Not sent') + ': ' + sent.sendError : ec.l10n.localize('Sent again'),
            sent.sendError ? 'warning' : 'success')
}

const out = ec.service.sync().name('org.moqui.comms.InboxServices.run#Operation').parameters({operation: 'get#MessageDetail', parameters: {emailMessageId: emailMessageId || ''}}).call()?.result || {}
if (!ec.message.hasError() && out?.detail?.kind !== 'email') ec.message.addError(ec.l10n.localize('Only an email downloads as an .eml file'))
if (ec.message.hasError()) { ec.web.sendJsonResponse({}); return }
const wasDisabled = out.detail.isSystemMail ? ec.artifactExecution.disableAuthz() : true
let exported = null
try {
    exported = ec.service.sync().name('org.moqui.impl.EmailClientServices.export#EmailMessage').parameter('emailMessageId', out.detail.emailMessageId).call()
} finally { if (!wasDisabled) ec.artifactExecution.enableAuthz() }
if (ec.message.hasError()) { ec.web.sendJsonResponse({}); return }
ec.web.sendTextResponse(exported.mimeText, exported.contentType, exported.fileName)

const out = ec.service.sync().name('org.moqui.comms.InboxServices.run#Operation').parameters({operation: 'get#MessageAttachment', parameters: {store: store || '', id: id || ''}}).call()?.result || {}
if (ec.message.hasError()) ec.web.sendJsonResponse({})
else ec.web.sendResourceResponse(out.location, String(inline) === 'true' && out.inlineAllowed)

const value = String(recordValue || '')
const at = value.indexOf('|')
if (at <= 0) ec.message.addError(ec.l10n.localize('Choose a record'))
else {
    const out = ec.service.sync().name('org.moqui.comms.InboxServices.run#Operation').parameters({operation: 'link#ThreadRecord', parameters: {emailMessageId: emailMessageId || null,
        communicationEventId: emailMessageId ? null : (communicationEventId || null), recordEntityName: value.substring(0, at), recordId: value.substring(at + 1)}}).call()?.result || {}
    if (!ec.message.hasError()) ec.message.addMessage(ec.l10n.localize('Linked') + (out.link ? ': ' + out.link.title : ''), 'success')
}
